<script>
$(function(){let i=$('.installment-row').length;$('#add-installment').click(()=>$('#installments').append(`<div class="installment-row row"><div class="col-md-4"><input class="form-control" name="installments[${i}][milestone]" placeholder="Milestone"></div><div class="col-md-3"><input class="form-control" type="number" name="installments[${i}][amount]" placeholder="Amount"></div><div class="col-md-3"><input class="form-control" type="number" name="installments[${i}][due_months]" placeholder="Due months"></div><div class="col-md-2"><button type="button" class="btn btn-outline-danger btn-block remove-row">Remove</button></div></div>`),i++);$(document).on('click','.remove-row',function(){$(this).closest('.installment-row').remove()});function fill(url,el,next){$.get(url,d=>{el.html('<option value="">Select</option>');d.forEach(x=>el.append(new Option(x.name,x.id,x.id==el.data('selected'),x.id==el.data('selected')));if(el.val()&&next)next()})}function districts(){if($('#division').val())fill('{{ url('/get-districts') }}/'+$('#division').val(),$('#district'),upazilas)}function upazilas(){if($('#district').val())fill('{{ url('/get-upazilas') }}/'+$('#district').val(),$('#upazila'),unions)}function unions(){if($('#upazila').val())fill('{{ url('/get-unions') }}/'+$('#upazila').val(),$('#union'))}$('#division').change(function(){$('#district,#upazila,#union').data('selected','');districts()});$('#district').change(function(){$('#upazila,#union').data('selected','');upazilas()});$('#upazila').change(function(){$('#union').data('selected','');unions()});districts();});
</script>
